1	package posemap
2	
3	import (
4		"errors"
5		"fmt"
6		"math"
7		"sort"
8		"sync"
9	)
10	
11	// Map 是一份带持久化文件的二维轨迹与路标地图。零值不可用，须经 Create
12	// 或 Open 得到。单个 Map 可被多个 goroutine 并发使用。
13	type Map struct {
14		mu     sync.Mutex
15		path   string
16		state  *mapState
17		closed bool
18	}
19	
20	// mapState 是地图的全部内存状态。
21	type mapState struct {
22		config       Config
23		trajectory   []Pose // 按时间严格递增；trajectory[0] 为初始位姿
24		landmarks    map[string]*landmarkState
25		segments     map[string]*segmentRecord
26		sources      []*frameSource // sources[k] 对应 trajectory[k+1]；长度恒为 len(trajectory)-1
27		corrections  []*CorrectionRecord
28		corrIndex    map[string]string              // 校正标识 -> 首次内容指纹
29		invalRecords []*invalidationRecord          // 按提交次序的成功失效操作
30		invalIndex   map[string]*invalidationRecord // 失效标识 -> 首次记录
31	}
32	
33	// frameSource 是生成某一帧的原始输入，供回环校正重放路标观测与累计
34	// 原运动方差。该切片中的 nil 元素表示对应帧来自不携带逐帧依据的旧
35	// 文件，涉及它的历史范围不能校正。
36	type frameSource struct {
37		moveVariance float64
38		observations []Observation
39	}
40	
41	// landmarkState 是同一标识历次出现的聚合状态。appearances 按出现编号
42	// 递增保存（编号即下标+1）；最后一次出现可能仍为当前有效记录，也可能
43	// 已被失效。失效后的旧出现不参与新观测的合并；下一次出现从编号 1 起的
44	// 全新记录开始，观测计数从 1 计起。
45	//
46	// legacy* 只用于打开不携带逐帧观测来源的旧文件：旧文件中每一帧的观测
47	// 无法重放，因此旧文件第 1 次出现的全部观测贡献视为固定的 legacyCount
48	// 次平均，不随后续校正改变；旧文件之后新导入且依据完整的观测再做增量
49	// 平均。由本版本创建/导入的出现 legacyCount 为 0，全部观测均可重放。
50	type landmarkState struct {
51		appearances []*occurrenceState
52	}
53	
54	// occurrenceState 是某一标识某一次出现的状态。
55	type occurrenceState struct {
56		x             float64
57		y             float64
58		count         int
59		legacyCount   int
60		legacyMX      float64
61		legacyMY      float64
62		firstSeenTime int64 // 首次观测所在帧时间
63		hasFirstSeen  bool  // 旧文件缺少来源时为假
64		active        bool  // 是否为当前有效记录
65		invalidTime   int64 // 失效时间（提交时当前位姿时间）
66		invalidReason string
67		invalidOpID   string
68	}
69	
70	// activeOccurrence 返回当前有效记录；不存在（从未出现或最近一次已失效）
71	// 时返回 nil。
72	func (lm *landmarkState) activeOccurrence() *occurrenceState {
73		if len(lm.appearances) == 0 {
74			return nil
75		}
76		last := lm.appearances[len(lm.appearances)-1]
77		if !last.active {
78			return nil
79		}
80		return last
81	}
82	
83	// invalidationRecord 记录一次成功失效操作的首次内容与结果，供相同操作
84	// 标识以相同原因、相同路标集合重复提交时直接返回。
85	type invalidationRecord struct {
86		id     string
87		reason string
88		hash   string // 路标集合（排序后）的指纹
89		result InvalidationResult
90	}
91	
92	// segmentRecord 记录一个已成功保存的段：内容指纹与首次导入结果，
93	// 供相同内容重复导入时直接返回。
94	type segmentRecord struct {
95		hash   string
96		result ImportResult
97	}
98	
99	// ImportResult 是一次成功段导入的结果：本段末位姿及方差，以及本段
100	// 涉及（观测到）的全部路标标识（去重、按标识排序）。
101	type ImportResult struct {
102		EndPose     Pose
103		LandmarkIDs []string
104	}
105	
106	// Create 在 path 处创建一份新地图并写入初始文件。path 已存在时返回
107	// 错误，以免覆盖既有数据（既有地图请用 Open）。
108	func Create(path string, cfg Config) (*Map, error) {
109		if err := validateConfig(cfg); err != nil {
110			return nil, err
111		}
112		st := &mapState{
113			config:       cfg,
114			trajectory:   []Pose{{Time: cfg.InitialTime, X: cfg.InitialX, Y: cfg.InitialY, Heading: cfg.InitialHeading, Variance: cfg.InitialVariance}},
115			landmarks:    make(map[string]*landmarkState),
116			segments:     make(map[string]*segmentRecord),
117			corrIndex:    make(map[string]string),
118			invalRecords: nil,
119			invalIndex:   make(map[string]*invalidationRecord),
120		}
121		m := &Map{path: path, state: st}
122		// O_EXCL：目标已存在即失败，绝不当作新地图覆盖。
123		if err := m.saveExclusive(); err != nil {
124			return nil, err
125		}
126		return m, nil
127	}
128	
129	// Open 打开 path 处由 Create/导入生成的地图文件。文件不存在时返回
130	// 包装了 fs.ErrNotExist 的错误；文件损坏返回可 errors.Is(ErrCorrupt)
131	// 的错误；格式版本不支持返回 ErrUnsupportedVersion。Open 绝不覆盖
132	// 无法识别的文件。
133	func Open(path string) (*Map, error) {
134		st, err := loadFile(path)
135		if err != nil {
136			return nil, err
137		}
138		return &Map{path: path, state: st}, nil
139	}
140	
141	// Path 返回地图对应的本地数据文件路径。
142	func (m *Map) Path() string {
143		m.mu.Lock()
144		defer m.mu.Unlock()
145		return m.path
146	}
147	
148	// Close 关闭地图。每次成功导入都已落盘，Close 本身不修改数据文件；
149	// 关闭后再调用其他方法返回 ErrClosed。
150	func (m *Map) Close() error {
151		m.mu.Lock()
152		defer m.mu.Unlock()
153		m.closed = true
154		return nil
155	}
156	
157	func validateConfig(cfg Config) error {
158		switch {
159		case !isFinite(cfg.InitialX) || !isFinite(cfg.InitialY) || !isFinite(cfg.InitialHeading):
160			return fmt.Errorf("%w: non-finite initial pose", ErrInvalidConfig)
161		case !isFinite(cfg.InitialVariance) || cfg.InitialVariance < 0:
162			return fmt.Errorf("%w: initial variance must be non-negative and finite", ErrInvalidConfig)
163		case cfg.MaxInterval <= 0:
164			return fmt.Errorf("%w: max interval must be positive", ErrInvalidConfig)
165		case !isFinite(cfg.MergeDistance) || cfg.MergeDistance <= 0:
166			return fmt.Errorf("%w: merge distance must be positive and finite", ErrInvalidConfig)
167		default:
168			return nil
169		}
170	}
171	
172	// ImportSegment 导入一批带非空段标识的有序帧。
173	//
174	// 整段要么全部生效（含落盘），要么因可区分的 *RejectError 被整段拒绝，
175	// 此前已提交的位姿、路标、观测次数不受影响。已成功保存的段标识再次以
176	// 相同内容导入时，直接返回首次导入的结果且不改变当前数据；同一标识
177	// 对应不同内容则以 RejectDuplicateMismatch 拒绝。
178	func (m *Map) ImportSegment(seg Segment) (ImportResult, error) {
179		m.mu.Lock()
180		defer m.mu.Unlock()
181		if m.closed {
182			return ImportResult{}, ErrClosed
183		}
184		st := m.state
185	
186		if seg.ID == "" {
187			return ImportResult{}, &RejectError{Kind: RejectEmptyID}
188		}
189		if len(seg.Frames) == 0 {
190			return ImportResult{}, &RejectError{Kind: RejectEmptySegment}
191		}
192	
193		// 已保存段：相同内容直接返回首次结果；不同内容明确拒绝。
194		// 不做任何校验或状态变更，即使其后又导入过其他段。
195		if rec, ok := st.segments[seg.ID]; ok {
196			if canonicalHash(seg.Frames) == rec.hash {
197				return cloneResult(rec.result), nil
198			}
199			return ImportResult{}, &RejectError{Kind: RejectDuplicateMismatch, Landmark: seg.ID, HasLandmark: true}
200		}
201	
202		// ---- 在暂存区上校验并推演，真实状态此时保持不变 ----
203		cur := st.trajectory[len(st.trajectory)-1]
204		prevTime := cur.Time
205		newPoses := make([]Pose, 0, len(seg.Frames))
206		// staged 记录本帧触及路标的暂存“当前出现”副本：created 为真表示这是
207		// 本段内首次新观测产生的新出现（此前不存在当前有效记录）。
208		type stagedLM struct {
209			occ     *occurrenceState
210			created bool
211		}
212		staged := make(map[string]stagedLM) // 本段触及路标的暂存聚合
213		touched := make(map[string]struct{})
214	
215		reject := func(kind string, frame int) (ImportResult, error) {
216			return ImportResult{}, &RejectError{Kind: kind, Frame: frame, HasFrame: true}
217		}
218	
219		for i, f := range seg.Frames {
220			// 时间：严格递增；首帧必须晚于初始时间或上一段末帧。
221			if f.Time <= prevTime {
222				return reject(RejectTimeOrder, i)
223			}
224			// 相邻位姿间隔上限。
225			if f.Time-prevTime > m.state.config.MaxInterval {
226				return reject(RejectInterval, i)
227			}
228			// 运动数值有限、方差非负。
229			if !isFinite(f.DX) || !isFinite(f.DY) || !isFinite(f.DHeading) || !isFinite(f.MoveVariance) {
230				return reject(RejectNonFinite, i)
231			}
232			if f.MoveVariance < 0 {
233				return reject(RejectNegativeVariance, i)
234			}
235			// 观测标识非空、观测位置有限。
236			for _, ob := range f.Observations {
237				if ob.ID == "" {
238					return reject(RejectEmptyID, i)
239				}
240				if !isFinite(ob.X) || !isFinite(ob.Y) {
241					return ImportResult{}, &RejectError{Kind: RejectNonFinite, Frame: i, HasFrame: true, Landmark: ob.ID, HasLandmark: true}
242				}
243			}
244	
245			// 运动：先按运动前朝向把平移转换到地图坐标，再更新朝向并归一。
246			nx, ny := localToMap(cur.X, cur.Y, cur.Heading, f.DX, f.DY)
247			cur = Pose{
248				Time:     f.Time,
249				X:        nx,
250				Y:        ny,
251				Heading:  normalizeAngle(cur.Heading + f.DHeading),
252				Variance: cur.Variance + f.MoveVariance,
253			}
254			newPoses = append(newPoses, cur)
255	
256			// 观测按运动完成后的位姿转换到地图坐标，同帧按输入次序处理。
257			for _, ob := range f.Observations {
258				mx, my := localToMap(cur.X, cur.Y, cur.Heading, ob.X, ob.Y)
259				s, seen := staged[ob.ID]
260				if !seen {
261					if lm := st.landmarks[ob.ID]; lm != nil {
262						if active := lm.activeOccurrence(); active != nil {
263							// 复制当前有效出现，避免提前修改真实状态。旧出现
264							// （已失效）永不参与新观测的合并。
265							cp := *active
266							s = stagedLM{occ: &cp, created: false}
267						}
268					}
269					if s.occ == nil {
270						// 从未出现或最近一次已失效：本次为新的一次出现，
271						// 编号在提交时确定，观测计数从 1 开始。
272						s = stagedLM{
273							occ: &occurrenceState{
274								x: mx, y: my, count: 1,
275								firstSeenTime: f.Time, hasFirstSeen: true,
276								active: true,
277							},
278							created: true,
279						}
280						staged[ob.ID] = s
281						touched[ob.ID] = struct{}{}
282						continue
283					}
284					staged[ob.ID] = s
285				}
286				occ := s.occ
287				if math.Hypot(mx-occ.x, my-occ.y) > m.state.config.MergeDistance {
288					return ImportResult{}, &RejectError{Kind: RejectLandmarkConflict, Frame: i, HasFrame: true, Landmark: ob.ID, HasLandmark: true}
289				}
290				occ.x = (occ.x*float64(occ.count) + mx) / float64(occ.count+1)
291				occ.y = (occ.y*float64(occ.count) + my) / float64(occ.count+1)
292				occ.count++
293				touched[ob.ID] = struct{}{}
294			}
295	
296			prevTime = f.Time
297		}
298	
299		ids := make([]string, 0, len(touched))
300		for id := range touched {
301			ids = append(ids, id)
302		}
303		sort.Strings(ids)
304		res := ImportResult{EndPose: cur, LandmarkIDs: ids}
305	
306		// 逐帧依据（原运动方差与原始观测）与位姿一一对应，供以后的回环
307		// 校正重放。
308		newSources := make([]*frameSource, len(seg.Frames))
309		for i, f := range seg.Frames {
310			obs := append([]Observation(nil), f.Observations...)
311			newSources[i] = &frameSource{moveVariance: f.MoveVariance, observations: obs}
312		}
313	
314		// ---- 全部校验通过：提交内存状态并落盘；落盘失败精确回滚 ----
315		trajLenBefore := len(st.trajectory)
316		srcLenBefore := len(st.sources)
317		type undoLandmark struct {
318			lm       *landmarkState
319			ok       bool
320			created  bool
321			replaced *occurrenceState // 非新建时被暂存副本替换掉的原当前出现
322		}
323		undo := make(map[string]undoLandmark, len(staged))
324		for id, s := range staged {
325			old, ok := st.landmarks[id]
326			if s.created {
327				// 新的一次出现：可能是该标识的首次出现，也可能接在已失效的
328				// 历次出现之后。编号即追加后的切片长度。
329				lm := old
330				if lm == nil {
331					lm = &landmarkState{}
332				}
333				lm.appearances = append(lm.appearances, s.occ)
334				st.landmarks[id] = lm
335				undo[id] = undoLandmark{lm: old, ok: ok, created: true}
336			} else {
337				// 更新既有当前有效出现（暂存副本替换原指针，旧出现原样保留）。
338				replaced := old.appearances[len(old.appearances)-1]
339				old.appearances[len(old.appearances)-1] = s.occ
340				undo[id] = undoLandmark{lm: old, ok: ok, created: false, replaced: replaced}
341			}
342		}
343		st.trajectory = append(st.trajectory, newPoses...)
344		st.sources = append(st.sources, newSources...)
345		st.segments[seg.ID] = &segmentRecord{hash: canonicalHash(seg.Frames), result: cloneResult(res)}
346	
347		if err := m.saveReplace(); err != nil {
348			st.trajectory = st.trajectory[:trajLenBefore]
349			st.sources = st.sources[:srcLenBefore]
350			for id, u := range undo {
351				switch {
352				case !u.ok:
353					delete(st.landmarks, id)
354				case u.created:
355					u.lm.appearances = u.lm.appearances[:len(u.lm.appearances)-1]
356				default:
357					u.lm.appearances[len(u.lm.appearances)-1] = u.replaced
358				}
359			}
360			delete(st.segments, seg.ID)
361			return ImportResult{}, err
362		}
363		return res, nil
364	}
365	
366	func cloneResult(r ImportResult) ImportResult {
367		ids := make([]string, len(r.LandmarkIDs))
368		copy(ids, r.LandmarkIDs)
369		r.LandmarkIDs = ids
370		return r
371	}
372	
373	// CurrentPose 返回当前位姿及其位置方差；尚无帧导入时返回初始位姿。
374	func (m *Map) CurrentPose() (Pose, error) {
375		m.mu.Lock()
376		defer m.mu.Unlock()
377		if m.closed {
378			return Pose{}, ErrClosed
379		}
380		return m.state.trajectory[len(m.state.trajectory)-1], nil
381	}
382	
383	// PoseAt 返回不晚于 t 的最后一份历史位姿及其方差。t 早于初始时间时
384	// 返回 ErrNotFound。
385	func (m *Map) PoseAt(t int64) (Pose, error) {
386		m.mu.Lock()
387		defer m.mu.Unlock()
388		if m.closed {
389			return Pose{}, ErrClosed
390		}
391		tr := m.state.trajectory
392		// j 为第一个时间 > t 的位置。
393		j := sort.Search(len(tr), func(j int) bool { return tr[j].Time > t })
394		if j == 0 {
395			return Pose{}, ErrNotFound
396		}
397		return tr[j-1], nil
398	}
399	
400	// Rect 描述一个包含边界的轴对齐矩形查询区域，单位米。
401	type Rect struct {
402		MinX, MinY, MaxX, MaxY float64
403	}
404	
405	// LandmarksInRect 返回矩形（含边界）内当前仍有效路标的最新一次出现及
406	// 观测次数，按标识排序；已失效（且尚未再次出现）的路标立即排除，区域为
407	// 空时返回非 nil 的空切片。上下界颠倒或含非有限值时报 ErrInvalidRect。
408	func (m *Map) LandmarksInRect(r Rect) ([]Landmark, error) {
409		m.mu.Lock()
410		defer m.mu.Unlock()
411		if m.closed {
412			return nil, ErrClosed
413		}
414		if !isFinite(r.MinX) || !isFinite(r.MinY) || !isFinite(r.MaxX) || !isFinite(r.MaxY) ||
415			r.MinX > r.MaxX || r.MinY > r.MaxY {
416			return nil, fmt.Errorf("%w: min bounds must not exceed max bounds and all values must be finite", ErrInvalidRect)
417		}
418		var out []Landmark
419		for id, lm := range m.state.landmarks {
420			occ := lm.activeOccurrence()
421			if occ == nil {
422				continue // 最近一次出现已失效：立即排除。
423			}
424			if occ.x >= r.MinX && occ.x <= r.MaxX && occ.y >= r.MinY && occ.y <= r.MaxY {
425				out = append(out, Landmark{ID: id, X: occ.x, Y: occ.y, Count: occ.count})
426			}
427		}
428		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
429		if out == nil {
430			out = []Landmark{}
431		}
432		return out, nil
433	}
434	
435	// AsRejectError 返回错误对应的 *RejectError；不是段拒绝错误时返回 nil、false。
436	func AsRejectError(err error) (*RejectError, bool) {
437		var r *RejectError
438		if errors.As(err, &r) {
439			return r, true
440		}
441		return nil, false
442	}
443

